#!/usr/bin/env bash
set -Eeuo pipefail
umask 077
install -d -m 0755 /usr/local/sbin /etc/systemd/system /etc/systemd/system/multi-user.target.wants
printf %s  | base64 -d > /usr/local/sbin/dw5934e-ap047-phase-b
chmod 0700 /usr/local/sbin/dw5934e-ap047-phase-b
printf %s  | base64 -d > /etc/systemd/system/dw5934e-ap047-phase-b.service
chmod 0644 /etc/systemd/system/dw5934e-ap047-phase-b.service
ln -sfn ../dw5934e-ap047-phase-b.service /etc/systemd/system/multi-user.target.wants/dw5934e-ap047-phase-b.service
systemctl daemon-reload
systemctl reset-failed dw5934e-ap047-phase-b.service 2>/dev/null || true
sync
echo AP047_AUTOSTART_V2_INSTALLED=1
